TRIGGERED_ABILITY.RESOLUTION_TIME_ACTION:
local n = MTG():GetActionRepCount() local num_players = MTG():GetNumberOfPlayers()
if (n < num_players) then local player = MTG():GetNthPlayer(n)
if player ~= nil and player:GetTeam() ~= EffectController():GetTeam() then local filter = ClearFilter() filter:Add( FE_TYPE, OP_IS, CARD_TYPE_CREATURE ) filter:Add( FE_CONTROLLER, OP_IS, player ) player:ChooseItem( "CARD_QUERY_CHOOSE_CREATURE_TO_SACRIFICE", EffectDC():Make_Targets(n) ) end return true else for i=0,(num_players-1) do local player = MTG():GetNthPlayer(i) if player ~= nil and player:GetTeam() ~= EffectController():GetTeam() then local creature = EffectDC():Get_Targets(i):Get_CardPtr(0) if creature ~= nil then player:Sacrifice( creature ) end end end end return false

if MTG():GetNumberOfStartingPlayers() > 2 then -- there is an actual choice so time to decide which oppoenent local filter = ClearFilter() filter:SetFilterType( FILTER_TYPE_PLAYERS ) filter:Add( FE_TEAM, OP_NOT, EffectController():GetTeam() ) EffectController():ChooseItem( "CARD_QUERY_CHOOSE_A_PLAYER_TO_ATTACK", EffectDC():Make_Targets(0) )
else -- we are only in a two player duel so we just grab the first oppoenent as we only have one for i = 0, (MTG():GetNumberOfPlayers()-1) do local player = MTG():GetNthPlayer(i)
if player ~= nil and player ~= EffectController() then EffectDC():Make_Targets(0):Set_PlayerPtr(0, player) end end end

local answerDC = EffectDC():Make_Targets(0) local queryDC = EffectDC():Make_Chest(1) local player = EffectController() for i = 0, (4-1) do local card = player:Library_GetNth(i)
if card ~= nil then queryDC:Set_CardPtr(i, card)
if (card:GetCardType():Test(CARD_TYPE_LAND)) == false then queryDC:QueryUnselect_CardPtr(i) end else break end end player:ChooseItemFromDC( "CARD_QUERY_CHOOSE_LAND_TO_PUT_INTO_HAND", queryDC, answerDC, QUERY_FLAG_MAY)

local effectController = EffectController()
local numPlayers = MTG():GetNumberOfPlayers() local lifeToGain = 0
for i = 0, (numPlayers-1) do local currentPlayer = MTG():GetNthPlayer(i) if currentPlayer ~= nil and currentPlayer:GetTeam() ~= effectController:GetTeam() then local lifeLost = currentPlayer:LoseLife(1) lifeToGain = lifeToGain+lifeLost end end effectController:GainLife(lifeToGain)
